func TestInPlaceOnlyWritesChanged(t *testing.T) {
	dir := t.TempDir()
	unchanged := filepath.Join(dir, "unchanged.rb")
	changed := filepath.Join(dir, "changed.rb")
	writeFile(t, unchanged, "a(1, 2, 3)\n")
	writeFile(t, changed, "a 1,2,3\n")
	beforeUnchanged, err := os.Stat(unchanged)
	if err != nil {
		t.Fatal(err)
	}
	beforeChanged, err := os.Stat(changed)
	if err != nil {
		t.Fatal(err)
	}
	time.Sleep(20 * time.Millisecond)
	result := runRubyfmt(t, dir, "", "-i", unchanged, changed)
	if result.code != 0 || result.stdout != "" {
		t.Fatalf("unexpected result: %+v", result)
	}
	afterUnchanged, _ := os.Stat(unchanged)
	afterChanged, _ := os.Stat(changed)
	unchangedContent, _ := os.ReadFile(unchanged)
	changedContent, _ := os.ReadFile(changed)
	if string(unchangedContent) != "a(1, 2, 3)\n" || string(changedContent) != "a(1, 2, 3)\n" {
		t.Fatalf("unexpected file contents: %q %q", unchangedContent, changedContent)
	}
	if !afterUnchanged.ModTime().Equal(beforeUnchanged.ModTime()) {
		t.Fatal("unchanged file mtime changed")
	}
	if afterChanged.ModTime().Equal(beforeChanged.ModTime()) {
		t.Fatal("changed file mtime did not change")
	}
}

