	result := runRubyfmt(t, dir, "", "-i", ".")
	if result.code != 0 {
		t.Fatalf("unexpected result: %+v", result)
	}
	content, _ := os.ReadFile(path)
	if string(content) != "a 1,2,3\n" {
		t.Fatal("gitignored file was formatted without --include-gitignored")
	}
	result = runRubyfmt(t, dir, "", "-i", "--include-gitignored", ".")
