package formatter

import (
	"bytes"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"sort"
	"strings"
	"testing"
)

func repoRoot(t testing.TB) string {
	t.Helper()
	_, file, _, ok := runtime.Caller(0)
	if !ok {
		t.Fatal("could not locate test source")
	}
	dir := filepath.Dir(file)
	for {
		if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
			return dir
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			t.Fatal("could not locate repository root")
		}
		dir = parent
	}
}

type fixturePair struct {
	actual   string
	expected string
}

func collectFixtures(t testing.TB, root string) []fixturePair {
	t.Helper()
	fixturesDir := filepath.Join(root, "fixtures")
	byPrefix := map[string]*fixturePair{}
	err := filepath.WalkDir(fixturesDir, func(path string, entry os.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if entry.IsDir() {
			return nil
		}
		name := entry.Name()
		var prefix string
		switch {
		case strings.HasSuffix(name, "_actual.rb"):
			prefix = strings.TrimSuffix(path, "_actual.rb")
			pair := byPrefix[prefix]
			if pair == nil {
				pair = &fixturePair{}
				byPrefix[prefix] = pair
			}
			pair.actual = path
		case strings.HasSuffix(name, "_expected.rb"):
			prefix = strings.TrimSuffix(path, "_expected.rb")
			pair := byPrefix[prefix]
			if pair == nil {
				pair = &fixturePair{}
				byPrefix[prefix] = pair
			}
			pair.expected = path
		}
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
	prefixes := make([]string, 0, len(byPrefix))
	for prefix := range byPrefix {
		prefixes = append(prefixes, prefix)
	}
	sort.Strings(prefixes)
	pairs := make([]fixturePair, 0, len(prefixes))
	for _, prefix := range prefixes {
		pair := byPrefix[prefix]
		if pair.actual != "" && pair.expected != "" {
			pairs = append(pairs, *pair)
		}
	}
	return pairs
}

func TestFixtures(t *testing.T) {
	root := repoRoot(t)
	binary := builtRubyfmt(t)
	pairs := collectFixtures(t, root)
	if len(pairs) == 0 {
		t.Fatal("no fixture pairs found")
	}
	for _, pair := range pairs {
		pair := pair
		name, _ := filepath.Rel(filepath.Join(root, "fixtures"), pair.actual)
		name = strings.TrimSuffix(name, "_actual.rb")
		name = strings.ReplaceAll(name, string(filepath.Separator), "_")
		t.Run(name, func(t *testing.T) {
			t.Parallel()
			expected, err := os.ReadFile(pair.expected)
			if err != nil {
				t.Fatal(err)
			}
			got := formatThroughCLI(t, binary, pair.actual)
			if !bytes.Equal(got, expected) {
				t.Fatalf("actual did not match expected\n%s", firstDiff(expected, got))
			}
			got = formatThroughCLI(t, binary, pair.expected)
			if !bytes.Equal(got, expected) {
				t.Fatalf("expected was not idempotent\n%s", firstDiff(expected, got))
			}
		})
	}
}

func formatThroughCLI(t *testing.T, binary, path string) []byte {
	t.Helper()
	command := exec.Command(binary, path)
	var stdout, stderr bytes.Buffer
	command.Stdout = &stdout
	command.Stderr = &stderr
	if err := command.Run(); err != nil {
		t.Fatalf("rubyfmt %s failed: %v\n%s", path, err, stderr.String())
	}
	return stdout.Bytes()
}

func firstDiff(expected, got []byte) string {
	expectedLines := strings.Split(string(expected), "\n")
	gotLines := strings.Split(string(got), "\n")
	limit := len(expectedLines)
	if len(gotLines) < limit {
		limit = len(gotLines)
	}
	for i := 0; i < limit; i++ {
		if expectedLines[i] != gotLines[i] {
			return "first difference at line " + itoa(i+1) + "\nexpected: " + expectedLines[i] + "\ngot:      " + gotLines[i]
		}
	}
	if len(expectedLines) != len(gotLines) {
		return "different line counts"
	}
	return "outputs differ"
}

func itoa(value int) string {
	if value == 0 {
		return "0"
	}
	var digits [20]byte
	i := len(digits)
	for value > 0 {
		i--
		digits[i] = byte('0' + value%10)
		value /= 10
	}
	return string(digits[i:])
}

