func TestFormatBufferPublicSyntaxErrorExitCode(t *testing.T) {
	_, err := rubyfmt.FormatBuffer([]byte("a 1,2,,\n"))
	if err == nil {
		t.Fatal("expected a syntax error")
	}
	if err.Kind != rubyfmt.FormatSyntaxError {
		t.Fatalf("unexpected error kind: %v", err.Kind)
	}
	if err.ExitCode() != 1 {
		t.Fatalf("unexpected exit code: %d", err.ExitCode())
	}
	if rubyfmt.ExitCode(err) != 1 {
		t.Fatalf("unexpected mapped exit code: %d", rubyfmt.ExitCode(err))
	}
	if rubyfmt.ExitCode(nil) != 0 {
		t.Fatalf("nil error should map to exit code 0")
	}
}
